using System.Text.Json;namespace PlayerOne.Windows.Services;
public sealed record EpisodeItem(string Id,string Title,int Season,int Episode,string StreamUrl);
public sealed class SeriesService{readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(30)};public async Task<List<EpisodeItem>> LoadXtreamAsync(string h,string u,string p,string sid){var url=$"{h.TrimEnd('/')}/player_api.php?username={Uri.EscapeDataString(u)}&password={Uri.EscapeDataString(p)}&action=get_series_info&series_id={Uri.EscapeDataString(sid)}";using var d=JsonDocument.Parse(await http.GetStringAsync(url));var r=new List<EpisodeItem>();if(!d.RootElement.TryGetProperty("episodes",out var ss))return r;foreach(var s in ss.EnumerateObject())foreach(var e in s.Value.EnumerateArray()){var id=e.TryGetProperty("id",out var i)?i.ToString():"";var en=e.TryGetProperty("episode_num",out var n)&&int.TryParse(n.ToString(),out var ev)?ev:1;var sn=int.TryParse(s.Name,out var sv)?sv:1;var ext=e.TryGetProperty("container_extension",out var ce)?ce.ToString():"mp4";var title=e.TryGetProperty("title",out var t)?t.ToString():$"Episode {en}";r.Add(new(id,title,sn,en,$"{h.TrimEnd('/')}/series/{Uri.EscapeDataString(u)}/{Uri.EscapeDataString(p)}/{id}.{ext}"));}return r;}}